for n, a, b, c, d, l in C:
    L += [f'## Неделя {n}', '', f'👶 **Что нормально:** {a}', f'💡 **Совет недели:** {b}', f'🩺 **К врачу, если:** {c}' if c != '—' else '🩺 **К врачу:** если что-то настораживает — спросите педиатра.', f'📅 **Напоминание:** {d}' if d != '—' else '', f'👉 Подробно: for-mom.ru{l}', '']
open(os.path.join(OUT, '52-nedeli.md'), 'w', encoding='utf-8').write('\n'.join(x for x in L if x is not None) + '\n')
